import{_ as r,o as a,c as e,ag as o}from"./chunks/framework.Aev9KvMf.js";const b=JSON.parse('{"title":"医疗机构与执业医师查询 · 防山寨医院假医生","description":"医院和医生资质官方查询教程：卫健委政务服务平台\\"查信息\\"频道核对医疗机构执业登记与医师执业注册，防山寨医院与假医生。","frontmatter":{"title":"医疗机构与执业医师查询 · 防山寨医院假医生","issuer":"国家卫生健康委员会（政务服务平台）","source_tier":"一级来源","version":"—","published":"—","source_url":"https://zwfw.nhc.gov.cn/cxx/","status":"现行服务","tags":["官方查询","医疗机构","执业医师","防坑"],"type":"查询页","reviewed":false,"description":"医院和医生资质官方查询教程：卫健委政务服务平台\\"查信息\\"频道核对医疗机构执业登记与医师执业注册，防山寨医院与假医生。"},"headers":[],"relativePath":"query/hospital-doctor.md","filePath":"query/hospital-doctor.md"}'),d={name:"query/hospital-doctor.md"};function h(n,t,l,s,i,c){return a(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="医疗机构与执业医师查询-·-防山寨医院假医生" tabindex="-1">医疗机构与执业医师查询 · 防山寨医院假医生 <a class="header-anchor" href="#医疗机构与执业医师查询-·-防山寨医院假医生" aria-label="Permalink to &quot;医疗机构与执业医师查询 · 防山寨医院假医生&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">待核验</p><p>本页由 AI 依据官方平台实测整理（浏览器核验&quot;查信息&quot;频道结构），具体查询表单以平台实际页面为准；入口改版时以卫健委官网为准。</p></div><blockquote><p><strong>官方入口</strong>：国家卫生健康委员会<a href="https://zwfw.nhc.gov.cn/cxx/" target="_blank" rel="noreferrer">政务服务平台&quot;查信息&quot;频道</a>（实测含：医卫机构查询——器官移植机构、爱婴医院名单、辅助生殖机构、产前诊断技术医疗机构；医卫人员查询——<strong>执业医师查询</strong>、<strong>执业护士查询</strong>；药物查询——基本药物目录等）。· 一级来源</p></blockquote><h2 id="速览卡" tabindex="-1">速览卡 <a class="header-anchor" href="#速览卡" aria-label="Permalink to &quot;速览卡&quot;">​</a></h2><p>在中国行医的医生必须有<strong>执业注册</strong>，医疗机构必须有<strong>执业许可</strong>。就医前花 30 秒核对，能挡住绝大多数山寨医院与假医生——尤其是搜索引擎广告和&quot;专家坐诊&quot;传单。</p><h2 id="_30-秒查询步骤-待核验" tabindex="-1">30 秒查询步骤（待核验） <a class="header-anchor" href="#_30-秒查询步骤-待核验" aria-label="Permalink to &quot;30 秒查询步骤（待核验）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>步骤</th><th>怎么做</th></tr></thead><tbody><tr><td>1</td><td>打开 <a href="https://zwfw.nhc.gov.cn/cxx/" target="_blank" rel="noreferrer">卫健委政务服务平台&quot;查信息&quot;</a></td></tr><tr><td>2</td><td><strong>查医生</strong>：选&quot;执业医师查询&quot;，输入姓名 + 省份（可加机构名）</td></tr><tr><td>3</td><td><strong>查机构</strong>：按分类选机构查询（医院、辅助生殖机构、产前诊断机构等专项名单）</td></tr><tr><td>4</td><td>核对结果：<strong>执业地点、执业范围、有效状态</strong>与对方宣称是否一致</td></tr></tbody></table><h2 id="结果怎么读" tabindex="-1">结果怎么读 <a class="header-anchor" href="#结果怎么读" aria-label="Permalink to &quot;结果怎么读&quot;">​</a></h2><table tabindex="0"><thead><tr><th>看到什么</th><th>说明</th></tr></thead><tbody><tr><td>医师查到，执业地点包含该机构</td><td>正常（<a href="https://zwfw.nhc.gov.cn/cxx/" target="_blank" rel="noreferrer">查信息频道</a>）</td></tr><tr><td>查无此人</td><td>无注册执业——宣传的&quot;专家&quot;身份存疑</td></tr><tr><td>医师真实但执业地点不含该机构</td><td>&quot;飞刀&quot;外聘或夸大宣传，谨慎核实</td></tr><tr><td>机构在专项名单（如辅助生殖）中查无</td><td>该机构无资质开展此类业务</td></tr></tbody></table><h2 id="避坑要点" tabindex="-1">避坑要点 <a class="header-anchor" href="#避坑要点" aria-label="Permalink to &quot;避坑要点&quot;">​</a></h2><table tabindex="0"><thead><tr><th>骗局话术</th><th>官方依据</th></tr></thead><tbody><tr><td>&quot;北京退休老专家坐诊&quot;</td><td>执业医师查询里查不到注册信息即无执业资格</td></tr><tr><td>&quot;不孕不育/疑难杂症专科&quot;</td><td>辅助生殖、产前诊断等有专项机构名单，名单外无资质</td></tr><tr><td>【本站提示】搜索引擎置顶的医疗广告与官网排场无关，资质只认注册查询</td><td>—</td></tr></tbody></table><h2 id="相关查询" tabindex="-1">相关查询 <a class="header-anchor" href="#相关查询" aria-label="Permalink to &quot;相关查询&quot;">​</a></h2><ul><li>药品：<a href="/SageRelay/query/drug.html">药品批准文号查询</a></li><li>化妆品：<a href="/SageRelay/query/cosmetics.html">化妆品备案/注册查询</a></li></ul><h2 id="溯源" tabindex="-1">溯源 <a class="header-anchor" href="#溯源" aria-label="Permalink to &quot;溯源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>内容</th></tr></thead><tbody><tr><td>平台</td><td>国家卫生健康委员会政务服务平台（一级来源）</td></tr><tr><td>入口</td><td><a href="https://zwfw.nhc.gov.cn/cxx/" target="_blank" rel="noreferrer">zwfw.nhc.gov.cn/cxx</a>（入口以卫健委官网为准）</td></tr></tbody></table>',15)])])}const q=r(d,[["render",h]]);export{b as __pageData,q as default};
